import json
from pathlib import Path

lists = json.loads(Path('data/vocabulary.json').read_text(encoding='utf-8'))['lists']
data = json.dumps(lists, ensure_ascii=False)
page = r'''<!-- Paste everything in this file into Google Sites: Insert > Embed > Embed code. -->
<style>
#vocab-steps{font:18px Arial,sans-serif;color:#17211e;background:#fbfaf4;max-width:850px;margin:auto;padding:28px;box-sizing:border-box}#vocab-steps *{box-sizing:border-box}#vocab-steps h1,#vocab-steps h2{font-family:Georgia,serif;line-height:1.1}#vocab-steps h1{font-size:clamp(36px,6vw,58px);margin:8px 0 18px}#vocab-steps h2{font-size:38px}#vocab-steps .hidden{display:none!important}#vocab-steps .eyebrow{font:700 12px monospace;letter-spacing:.12em;color:#145c47}#vocab-steps .intro,#vocab-steps .muted{color:#52625b;line-height:1.5}#vocab-steps .setup{margin:25px 0}#vocab-steps h3{font-size:16px;margin:22px 0 8px}#vocab-steps .choices-row,#vocab-steps .list-choices{display:flex;gap:10px;flex-wrap:wrap}#vocab-steps .card,#vocab-steps .choices-row label{border:1px solid #c9d2cb;border-radius:5px;background:#fff;padding:10px 13px;cursor:pointer}#vocab-steps .card{min-width:190px}#vocab-steps input[type=radio],#vocab-steps input[type=checkbox]{accent-color:#145c47}#vocab-steps small{display:block;color:#62736a;margin:4px 0 0 22px;font-size:13px}#vocab-steps button{border:0;border-radius:4px;padding:12px 18px;background:#145c47;color:#fff;font-weight:bold;font-size:16px;cursor:pointer}#vocab-steps button:hover{background:#0e4636}#vocab-steps input[type=text]{padding:12px;border:1px solid #9faca4;border-radius:4px;font-size:16px;min-width:280px}#vocab-steps form{display:flex;gap:9px;flex-wrap:wrap}#vocab-steps .bar{height:8px;border-radius:8px;background:#dfe6df;margin:20px 0 34px}#vocab-steps .bar i{display:block;height:100%;width:0;background:#e2633b;border-radius:inherit}#vocab-steps .answers{display:grid;grid-template-columns:1fr 1fr;gap:9px;max-width:650px}#vocab-steps .answers button{background:#fff;color:#17211e;border:1px solid #c9d2cb;text-align:left}#vocab-steps .feedback{margin:18px 0;padding:13px;border-left:5px solid #145c47;background:#e4efe8}#vocab-steps .wrong{border-color:#e2633b;background:#fff0e9}@media(max-width:550px){#vocab-steps .answers{grid-template-columns:1fr}}
</style>
<div id="vocab-steps"><section data-page="home"><p class="eyebrow">STUDY SETUP</p><h1>Choose your<br>next challenge.</h1><p class="intro">Choose one or more lists and how you want to practice.</p><div class="setup"><h3>Vocabulary lists</h3><p class="muted">Choose one or more lists to study together.</p><div class="list-choices"></div><h3>Answer with</h3><div class="choices-row"><label><input type="radio" name="vs-direction" value="word" checked> Vocabulary word<small>See the definition</small></label><label><input type="radio" name="vs-direction" value="definition"> Definition<small>See the word</small></label></div><h3>Answer style</h3><div class="choices-row"><label><input type="radio" name="vs-style" value="typing" checked> Type my answer</label><label><input type="radio" name="vs-style" value="multiple"> Multiple choice</label></div><h3>Study length</h3><div class="choices-row"><label><input type="radio" name="vs-length" value="complete" checked> Finish list in order<small>Default · complete every word</small></label><label><input type="radio" name="vs-length" value="endless"> Endless mode<small>Balanced random five-word sets</small></label></div></div><button data-start>Start a set</button><p class="muted">5 questions per set</p></section><section data-page="quiz" class="hidden"><p class="eyebrow" data-progress></p><div class="bar"><i></i></div><h2 data-word></h2><p data-prompt></p><form data-form><input type="text" autocomplete="off" required><button>Check answer</button></form><div data-answers class="answers hidden"></div><div data-feedback class="feedback hidden"></div><button data-next class="hidden">Next word</button></section><section data-page="done" class="hidden"><p class="eyebrow" data-done-label></p><h1 data-done-title></h1><p class="intro" data-done-text></p><button data-again></button></section><p class="muted">Vocab updated by Gavin Vukan</p></div>
<script>
(()=>{const lists=__DATA__,r=document.querySelector('#vocab-steps'),q=s=>r.querySelector(s),qa=s=>[...r.querySelectorAll(s)],clean=x=>String(x).trim().toLowerCase(),shuffle=a=>{a=[...a];for(let i=a.length-1;i;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a},show=x=>qa('[data-page]').forEach(e=>e.classList.toggle('hidden',e.dataset.page!==x));let activeWords=[],queue=[],questions=[],current=0,mastered=0,set=1,nextWord=0,batch=0,endless=false,dir='word',style='typing';q('.list-choices').innerHTML=lists.map((x,i)=>`<label class="card"><input type="checkbox" name="vs-list" value="${x.id}" ${i?'':'checked'}><strong>${x.name}</strong><small>${x.description}</small></label>`).join('');const answer=w=>dir==='word'?w.word:w.definition,prompt=w=>dir==='word'?w.definition:w.word;function begin(){let ids=qa('[name=vs-list]:checked').map(x=>x.value);if(!ids.length)return alert('Choose at least one vocabulary list.');activeWords=lists.filter(x=>ids.includes(x.id)).flatMap(x=>x.words);dir=q('[name=vs-direction]:checked').value;style=q('[name=vs-style]:checked').value;endless=q('[name=vs-length]:checked').value==='endless';set=1;nextWord=0;queue=[];start()}function balanced(n){while(queue.length<n){let cycle=shuffle(activeWords);if(queue.length&&cycle.length>1&&queue.at(-1).id===cycle[0].id)[cycle[0],cycle[1]]=[cycle[1],cycle[0]];queue.push(...cycle)}return queue.splice(0,n)}function start(){questions=endless?balanced(5):activeWords.slice(nextWord,nextWord+5);batch=questions.length;current=mastered=0;show('quiz');draw()}function draw(){let w=questions[current];q('[data-progress]').textContent=`SET ${set} · ${mastered} OF ${batch} MASTERED`;q('.bar i').style.width=`${mastered/batch*100}%`;q('[data-word]').textContent=prompt(w);q('[data-prompt]').textContent=dir==='word'?'Which vocabulary word matches this definition?':'What does this vocabulary word mean?';q('[data-feedback]').classList.add('hidden');q('[data-next]').classList.add('hidden');if(style==='typing'){q('[data-form]').classList.remove('hidden');q('[data-answers]').classList.add('hidden');let i=q('[data-form] input');i.value='';i.placeholder=dir==='word'?'Type the vocabulary word…':'Type the definition…';i.focus()}else{q('[data-form]').classList.add('hidden');let opts=shuffle([answer(w),...shuffle(activeWords.filter(x=>x.id!==w.id)).slice(0,3).map(answer)]);let box=q('[data-answers]');box.innerHTML=opts.map(x=>`<button>${x}</button>`).join('');box.classList.remove('hidden');qa('[data-answers] button').forEach(b=>b.onclick=()=>grade(b.textContent))}}function grade(x){let w=questions[current],ok=clean(x)===clean(answer(w));if(ok)mastered++;else questions.push(w);q('[data-form]').classList.add('hidden');q('[data-answers]').classList.add('hidden');let f=q('[data-feedback]');f.className=`feedback ${ok?'':'wrong'}`;f.innerHTML=ok?'<strong>Correct!</strong> Nice work.':`<strong>Not quite.</strong> The correct answer is: ${answer(w)}<br><small>You will see this word again before the set is complete.</small>`;q('[data-next]').textContent=ok&&mastered===batch?'Finish set':'Next word';q('[data-next]').classList.remove('hidden')}function done(){if(!endless)nextWord+=batch;let final=!endless&&nextWord>=activeWords.length;q('[data-done-label]').textContent=final?'LIST COMPLETE':'SET COMPLETE';q('[data-done-title]').textContent=final?'You mastered the selected lists.':'Excellent work.';q('[data-done-text]').textContent=final?`You answered all ${activeWords.length} selected vocabulary words correctly.`:endless?'Ready for a fresh balanced random set?':`${Math.min(nextWord,activeWords.length)} of ${activeWords.length} words completed. Continue with the next five words.`;q('[data-again]').textContent=final?'Back to home':endless?'Start next balanced set':`Start set ${set+1}`;q('[data-again]').dataset.final=final;show('done')}q('[data-start]').onclick=begin;q('[data-form]').onsubmit=e=>{e.preventDefault();grade(q('[data-form] input').value)};q('[data-next]').onclick=()=>{if(++current===questions.length)done();else draw()};q('[data-again]').onclick=()=>{if(q('[data-again]').dataset.final==='true')show('home');else{set++;start()}};r.addEventListener('keydown',e=>{if(e.key==='Enter'&&!q('[data-next]').classList.contains('hidden')){e.preventDefault();q('[data-next]').click()}})})();
</script>'''.replace('__DATA__', data)
Path('google-sites-embed.html').write_text(page, encoding='utf-8')
